records=[]
for ident,path,names,behavior,risk,recommendation in rows:
    m=json.loads((WORK/'Knowledge/Source-Symbols'/(path+'.json')).read_text(encoding='utf-8-sig'))
    blob=subprocess.check_output(['git','show',BASELINE+':'+path],cwd=ROOT)
    raw=(ROOT/path).read_bytes()
    if hashlib.sha256(blob).hexdigest()!=m['git_blob_sha256'] or hashlib.sha256(raw).hexdigest()!=m['worktree_sha256']:raise ValueError(path+' changed')
    syms=[{k:s[k] for k in ['stable_id','kind','name','qualifiedSymbol','startLine','startColumn','endLine','endColumn']} for s in m['symbols'] if s['kind'] in ['MethodDeclaration','ConstructorDeclaration'] and any(n in (s.get('qualifiedSymbol','')+' '+s['name']) for n in names)]
    records.append({'candidate_id':ident,'classification':'SOURCE_CONFIRMED_BEHAVIOR_WITH_UNMEASURED_PERFORMANCE_IMPACT','path':path,'baseline_git_blob_sha256':m['git_blob_sha256'],'worktree_sha256':m['worktree_sha256'],'source_symbols':syms,'review_scope':'performance-focused source reasoning; not exhaustive security/business review of all symbols','behavior':behavior,'risk_and_counterevidence':risk,'recommendation_and_tests':recommendation,'independent_verification':'PENDING','runtime_measurement':'NOT_EXECUTED'})
